    }

    include_dirs = []
    if ((target_name == "libark_jsruntime_arm_set" ||
        target_name == "libark_jsruntime_dfx_arm_set") && is_ohos &&
        is_standard_system && !is_arkui_x && target_cpu == "arm64") {
      include_dirs += [
